    target = total_sum // 2
    possible_sums = {0}

    for num in nums:
        new_sums = set()
        for s in possible_sums:
            if s + num <= target:
                new_sums.add(s + num)
        possible_sums.update(new_sums)
        if target in possible_sums:
            return True

    return False"

