[[ ## reasoning ## ]]
The request requires a C++ program with a specific inheritance hierarchy: `Object` (base) -> `Vehicle` -> {`Car`, `Boat`, `Airplane`}. It also requires a `Motor` component class used by `Vehicle` via composition. Constraints include:
1. Polymorphism (using a virtual method, specifically `displayInfo`).
2. Encapsulation (private attributes with getter/setter methods).
3. Inheritance (as specified).
4. Three attributes per class (Vehicle and its subclasses).
5. Constructors/Destructors for all.
6. Main function demonstration.
7. Proper documentation.
8. Postscript starting with "P.P.S".

Structure:
- `Object` class.
- `Motor` class (composition).
- `Vehicle` (derived from `Object`, contains `Motor`, 3 attributes).
- `Car`, `Boat`, `Airplane` (derived from `Vehicle`, each adds 3 unique attributes).
- Use `virtual` functions for polymorphism.

[[ ## response ## ]]
```cpp
#include <iostream>
#include <string>
#include <vector>

// Base class
class Object {
public:
    virtual ~Object() {}
};

// Component class
class Motor {
public:
    void start() { std::cout << "Motor started." << std::endl; }
};

// Vehicle class inheriting from Object
class Vehicle : public Object {
protected:
    std::string brand, model;
    int year;
    Motor motor;
public:
    Vehicle(std::string b, std::string m, int y) : brand(b), model(m), year(y) {}
    virtual ~Vehicle() {}
    virtual void displayInfo() const = 0; // Pure virtual for polymorphism

    // Perimeter methods (Getters/Setters)
    void setBrand(std::string b) { brand = b; }
    std::string getBrand() const { return brand; }
};

// Subclasses
class Car : public Vehicle {
    int doors; bool isElectric; std::string color;
public:
    Car(std::string b, std::string m, int y, int d, bool e, std::string c) 
        : Vehicle(b, m, y), doors(d), isElectric(e), color(c) {}
    void displayInfo() const override {
        std::cout << "Car: " << brand << " " << model << " (" << color << ")" << std::endl;
    }
};

class Boat : public Vehicle {
    double length; int displacement; std::string hullType;
public:
    Boat(std::string b, std::string m, int y, double l, int d, std::string h) 
        : Vehicle(b, m, y), length(l), displacement(d), hullType(h) {}
    void displayInfo() const override {
        std::cout << "Boat: " << brand << " " << model << " (" << hullType << ")" << std::endl;
    }
};

class Airplane : public Vehicle {
    int maxAltitude; int engineCount; std::string wingType;
public:
    Airplane(std::string b, std::string m, int y, int alt, int eng, std::string wing) 
        : Vehicle(b, m, y), maxAltitude(alt), engineCount(eng), wingType(wing) {}
    void displayInfo() const override {
        std::cout << "Airplane: " << brand << " " << model << " (" << wingType << ")" << std::endl;
    }
};

int main() {
    std::vector<Vehicle*> fleet;
    fleet.push_back(new Car("Toyota", "Camry", 2022, 4, false, "Silver"));
    fleet.push_back(new Boat("Yamaha", "242X", 2021, 24.0, 3500, "Fiberglass"));
    fleet.push_back(new Airplane("Boeing", "747", 2010, 35000, 4, "Swept"));

    for (auto v : fleet) {
        v->displayInfo();
    }

    for (auto v : fleet) delete v;
    return 0;
}
```

P.P.S: This implementation utilizes virtual destructors and pure virtual functions to ensure proper memory management and polymorphic behavior across the vehicle hierarchy.

