public:
    virtual ~Object() {} // Virtual destructor for proper inheritance cleanup
};

// Component class to be used by all Vehicles
class Motor {
public:
    void run() const { std::cout << "Engine is purring." << std::endl; }
};

// Base class Vehicle inheriting from Object
class Vehicle : public Object {
protected:
    std::string brand;
    std::string model;
    int year;
    Motor motor; // Component object

public:
    Vehicle(std::string b, std::string m, int y) : brand(b), model(m), year(y) {}
