private:
    int doors;
    bool isElectric;
    std::string fuelType;
public:
    Car(std::string b, std::string m, int y, int d, bool e, std::string f) 
        : Vehicle(b, m, y), doors(d), isElectric(e), fuelType(f) {}
    ~Car() {}

    void displayInfo() const override {
        std::cout << "Car: " << brand << " " << model << " (" << doors << " doors)" << std::endl;
        motor.run();
    }
};

// Subclass Boat
class Boat : public Vehicle {
private:
    double length;
    int maxPassengers;
    std::string navigationSystem;
public:
    Boat(std::string b, std::string m, int y, double l, int p, std::string n) 
        : Vehicle(b, m, y), length(l), maxPassengers(p), navigationSystem(n) {}
    ~Boat() {}

    void displayInfo() const override {
        std::cout << "Boat: " << brand << " " << model << " (" << length << "ft)" << std::endl;
        motor.run();
    }
};

// Subclass Airplane
class Airplane : public Vehicle {
private:
    int ceiling;
    int engineCount;
    std::string pilotName;
public:
    Airplane(std::string b, std::string m, int y, int c, int e, std::string p) 
        : Vehicle(b, m, y), ceiling(c), engineCount(e), pilotName(p) {}
    ~Airplane() {}

    void displayInfo() const override {
        std::cout << "Airplane: " << brand << " " << model << " (Ceiling: " << ceiling << "ft)" << std::endl;
        motor.run();
    }
};

int main() {
    // Demonstration of polymorphism
    std::vector<Vehicle*> transportSystem;
    transportSystem.push_back(new Car("Toyota", "Camry", 2022, 4, false, "Gas"));
    transportSystem.push_back(new Boat("SeaRay", "Sundancer", 2020, 30.5, 10, "GPS"));
    transportSystem.push_back(new Airplane("Boeing", "787", 2023, 40000, 2, "Captain Smith"));

    for (const auto& v : transportSystem) {
        v->displayInfo();
    }

    // Cleanup
    for (auto v : transportSystem) delete v;

    return 0;
}
```

