Approach 1: PostgreSQL Schema Isolation
This method uses shared infrastructure but isolates data through separate schemas within a single database, which is efficient for resource utilization.

-- Create schema for the tenant
CREATE SCHEMA tenant_alpha;

-- Create a dedicated role for the tenant
CREATE ROLE tenant_alpha_user WITH LOGIN PASSWORD 'strong_password';

-- Grant permissions
GRANT USAGE ON SCHEMA tenant_alpha TO tenant_alpha_user;
ALTER DEFAULT PRIVILEGES IN SCHEMA tenant_alpha GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO tenant_alpha_user;

******

Approach 2: Database-Level Isolation (MySQL/MariaDB style)
This method provides stronger isolation by creating a physically separate database for each tenant, ensuring that data is completely partitioned at the storage layer.

-- Create a separate database for the tenant
CREATE DATABASE tenant_beta_db;

-- Create a dedicated user for this database
CREATE USER 'beta_admin'@'localhost' IDENTIFIED BY 'secure_password';

-- Grant exclusive access to the specific database
GRANT ALL PRIVILEGES ON tenant_beta_db.* TO 'beta_admin'@'localhost';

-- Ensure the user cannot access other databases on the server
REVOKE ALL PRIVILEGES ON *.* FROM 'beta_admin'@'localhost';
FLUSH PRIVILEGES;
